 "content": "def transform(grid):
    """Fill the grid with the shortest repeating diagonal color pattern."""
    h, w = len(grid), len(grid[0])

    # Each clue lies on a diagonal identified by c-r. Distinct clues can
    # establish the same repeating residue, so find the shortest consistent
    # period and use the observed color for each residue.
    known = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != 0:
                known[c - r] = value

    period = next(
        (p for p in range(1, max(h, w) + 1)
         if all(known[a] == known[b]
                for a in known for b in known
                if (a - b) % p == 0)),
        max(h, w),
    )
    colors = {d % period: color for d, color in known.items()}

    return [
        [grid[r][c] or colors.get((c - r) % period, 0) for c in range(w)]
        for r in range(h)
    ]
